SET time_zone='+00:00';
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @fifo_cenario=CONVERT(@fifo_cenario USING utf8mb4) COLLATE utf8mb4_unicode_ci;
DELIMITER $$
DROP PROCEDURE IF EXISTS fifo_carregar$$
CREATE PROCEDURE fifo_carregar()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF DATABASE() IS NULL OR LEFT(DATABASE(),9) <> 'fifo_pdv_' THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FIFO exige banco isolado com prefixo correto';
 END IF;
 IF @fifo_cenario IS NULL OR @fifo_cenario NOT IN ('parcial','integral','perda','travessia','inicio_efetivo','inicio_futuro','historico') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Escolha um cenario FIFO documentado';
 END IF;
 CREATE TABLE IF NOT EXISTS fifo_fixture (id INT PRIMARY KEY, referencia DATE NOT NULL, cenario VARCHAR(30) NOT NULL);
 IF EXISTS(SELECT 1 FROM fifo_fixture WHERE referencia <> '2026-10-01' OR cenario <> @fifo_cenario) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Outra referencia/cenario: use banco novo';
 END IF;
 CREATE TABLE IF NOT EXISTS pdv_produto (restaurante_id BIGINT, id BIGINT, nome VARCHAR(100),
 tipo VARCHAR(20), unidade_medida VARCHAR(20), gramas_por_unidade INT, preco_venda DECIMAL(10,2),
 PRIMARY KEY(restaurante_id,id));
 CREATE TABLE IF NOT EXISTS pdv_ficha_tecnica (restaurante_id BIGINT, produto_id BIGINT, ingrediente_id BIGINT,
 quantidade_g INT, PRIMARY KEY(restaurante_id,produto_id,ingrediente_id),
 FOREIGN KEY(restaurante_id,produto_id) REFERENCES pdv_produto(restaurante_id,id),
 FOREIGN KEY(restaurante_id,ingrediente_id) REFERENCES pdv_produto(restaurante_id,id));
 CREATE TABLE IF NOT EXISTS pdv_compra (restaurante_id BIGINT, id BIGINT, produto_id BIGINT,
 compra_em TIMESTAMP(6), quantidade DECIMAL(18,6), preco_custo DECIMAL(18,8),
 unidade VARCHAR(20), gramas_por_unidade INT, data_validade DATE, PRIMARY KEY(restaurante_id,id),
 FOREIGN KEY(restaurante_id,produto_id) REFERENCES pdv_produto(restaurante_id,id));
 CREATE TABLE IF NOT EXISTS pdv_venda (restaurante_id BIGINT, id BIGINT, produto_id BIGINT,
 data_venda TIMESTAMP(6), quantidade INT, preco_unitario DECIMAL(10,2), valor_total DECIMAL(10,2),
 PRIMARY KEY(restaurante_id,id), FOREIGN KEY(restaurante_id,produto_id) REFERENCES pdv_produto(restaurante_id,id));
 CREATE TABLE IF NOT EXISTS pdv_estoque (restaurante_id BIGINT, lote_id BIGINT, produto_id BIGINT,
 quantidade_atual_g INT, corte_em TIMESTAMP(6), PRIMARY KEY(restaurante_id,lote_id),
 FOREIGN KEY(restaurante_id,lote_id) REFERENCES pdv_compra(restaurante_id,id));
 IF NOT EXISTS(SELECT 1 FROM fifo_fixture) AND (EXISTS(SELECT 1 FROM pdv_produto)
 OR EXISTS(SELECT 1 FROM pdv_compra) OR EXISTS(SELECT 1 FROM pdv_venda)) THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Primeira carga exige PDV vazio'; END IF;
 START TRANSACTION;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_produto.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_ficha_tecnica.restaurante_id;
IF @fifo_cenario='parcial' THEN
ON DUPLICATE KEY UPDATE restaurante_id=pdv_compra.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_venda.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_estoque.restaurante_id;
END IF;
IF @fifo_cenario='integral' THEN
ON DUPLICATE KEY UPDATE restaurante_id=pdv_compra.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_venda.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_estoque.restaurante_id;
END IF;
IF @fifo_cenario='perda' THEN
ON DUPLICATE KEY UPDATE restaurante_id=pdv_compra.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_venda.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_estoque.restaurante_id;
END IF;
IF @fifo_cenario='travessia' THEN
ON DUPLICATE KEY UPDATE restaurante_id=pdv_compra.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_venda.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_estoque.restaurante_id;
END IF;
IF @fifo_cenario='inicio_efetivo' THEN
ON DUPLICATE KEY UPDATE restaurante_id=pdv_compra.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_venda.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_estoque.restaurante_id;
END IF;
IF @fifo_cenario='inicio_futuro' THEN
ON DUPLICATE KEY UPDATE restaurante_id=pdv_compra.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_venda.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_estoque.restaurante_id;
END IF;
IF @fifo_cenario='historico' THEN
ON DUPLICATE KEY UPDATE restaurante_id=pdv_compra.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_venda.restaurante_id;
ON DUPLICATE KEY UPDATE restaurante_id=pdv_estoque.restaurante_id;
END IF;
COMMIT;
END$$
CALL fifo_carregar()$$
DROP PROCEDURE fifo_carregar$$
DELIMITER ;
